import random
import string
from typing import List

# This generator produces valid UTF-8 NUL-terminated strings encoded as bytes,
# aimed at exercising mosquitto/mosqpp stubs that request FUZZ_PARAM_STR inputs.
# It focuses on MQTT-relevant strings: topics (with/without wildcards), client ids,
# usernames/passwords, PSK hex strings, property names/values, and command names.
# The output is a single bytes buffer that the harness will slice into multiple
# FUZZ_PARAM_STR returns as needed. We build a corpus-like bag of strings and
# join them with NUL separators so each FUZZ_PARAM_STR() can read a distinct
# NUL-terminated string. All strings are valid UTF-8.

# Helper: ensure a string contains only valid UTF-8 codepoints and avoid NUL chars.
def _rand_utf8_text(rng: random.Random, min_len: int, max_len: int, allow_extended: bool = True) -> str:
    length = rng.randint(min_len, max_len)
    # Build from a mix of ASCII and selected valid multi-byte sequences
    ascii_pool = string.ascii_letters + string.digits + " _-./@$:+#"  # include MQTT wildcards and separators
    s: List[str] = []
    while len(s) < length:
        # Bias toward ASCII to keep topics simple and valid
        if not allow_extended or rng.random() < 0.75:
            ch = rng.choice(ascii_pool)
            if ch == "\x00":
                continue
            s.append(ch)
        else:
            # Choose some safe Unicode ranges commonly accepted (BMP excluding surrogates)
            # Avoid control chars. Pick from:
            # - Latin-1 supplement letters, symbols
            # - Greek, Cyrillic
            # - CJK small set
            ranges = [
                (0x00A1, 0x00FF),
                (0x0370, 0x03FF),
                (0x0400, 0x04FF),
                (0x3041, 0x30FF),
                (0x4E00, 0x4E5F),
            ]
            start, end = rng.choice(ranges)
            cp = rng.randint(start, end)
            if 0xD800 <= cp <= 0xDFFF:
                continue  # exclude surrogates
            s.append(chr(cp))
    return "".join(s)

# MQTT topic helpers

def _valid_topic_no_wildcards(rng: random.Random) -> str:
    # Construct a topic that avoids '+' and '#' to satisfy publish checks
    levels = rng.randint(1, 5)
    parts = []
    for _ in range(levels):
        part = _rand_utf8_text(rng, 1, rng.randint(1, 12), allow_extended=True)
        part = part.replace("+", "x").replace("#", "x")
        # MQTT prohibits embedded NUL and empty levels are allowed except to avoid leading/trailing '/'
        part = part.strip()
        if part == "":
            part = "lvl"
        parts.append(part)
    return "/".join(parts)


def _valid_sub_filter(rng: random.Random) -> str:
    # Build subscription filters; may include '+' or '#' in valid positions
    # Rules: '#' only at end and must be its own level. '+' matches a single level.
    levels = rng.randint(1, 5)
    parts = []
    for i in range(levels):
        choice = rng.random()
        if choice < 0.15 and i == levels - 1:
            parts.append("#")
        elif choice < 0.35:
            parts.append("+")
        else:
            part = _rand_utf8_text(rng, 1, rng.randint(1, 12), allow_extended=True)
            part = part.replace("+", "x").replace("#", "x")
            part = part.strip() or "lvl"
            parts.append(part)
    # Ensure '#' only appears at last level and alone
    for i, p in enumerate(parts):
        if p == "#" and i != len(parts) - 1:
            parts[i] = "+"  # adjust to valid wildcard if misplaced
        elif "#" in p and p != "#":
            parts[i] = p.replace("#", "x")
    return "/".join(parts)


def _client_id(rng: random.Random) -> str:
    # Valid UTF-8, typical broker limits ~23+ chars; keep varied
    length = rng.randint(1, 30)
    pool = string.ascii_letters + string.digits + "_-"  # conservative
    return "".join(rng.choice(pool) for _ in range(length))


def _username(rng: random.Random) -> str:
    base = _rand_utf8_text(rng, 1, rng.randint(3, 16), allow_extended=True)
    return base.replace("\x00", "")


def _password(rng: random.Random) -> str:
    # Any bytes are fine for password in practice; but we must return UTF-8
    base = _rand_utf8_text(rng, 0, rng.randint(0, 20), allow_extended=True)
    return base


def _psk_hex(rng: random.Random) -> str:
    # At least one byte (2 hex chars)
    nbytes = rng.randint(1, 16)
    hexchars = "0123456789abcdef"
    return "".join(rng.choice(hexchars) for _ in range(nbytes * 2))


def _identity(rng: random.Random) -> str:
    s = _rand_utf8_text(rng, 1, rng.randint(3, 16), allow_extended=False)
    return s


def _prop_name(rng: random.Random) -> str:
    known = [
        "user-property",
        "content-type",
        "response-topic",
        "correlation-data",
        "subscription-identifier",
        "session-expiry-interval",
    ]
    if rng.random() < 0.6:
        return rng.choice(known)
    # generate kebab-case token
    words = [
        ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(3, 8)))
        for _ in range(rng.randint(1, 3))
    ]
    return "-".join(words)


def _command_name(rng: random.Random) -> str:
    cmds = [
        "CONNECT", "CONNACK", "PUBLISH", "PUBACK", "PUBREC", "PUBREL", "PUBCOMP",
        "SUBSCRIBE", "SUBACK", "UNSUBSCRIBE", "UNSUBACK", "PINGREQ", "PINGRESP", "DISCONNECT",
    ]
    if rng.random() < 0.7:
        return rng.choice(cmds)
    return _rand_utf8_text(rng, 3, 10, allow_extended=False).upper()


def _utf8_slices(rng: random.Random, s: str) -> List[str]:
    # Produce full string and some valid-prefix slices for APIs that may use explicit lengths
    out = [s]
    if len(s) > 0:
        for _ in range(rng.randint(0, 2)):
            cut = rng.randint(0, len(s))
            # ensure we cut on codepoint boundary; Python str indexes are code points already
            out.append(s[:cut])
    return out


def _bag_of_strings(rng: random.Random) -> List[str]:
    bag: List[str] = []
    # Topics and filters
    for _ in range(rng.randint(2, 5)):
        bag.extend(_utf8_slices(rng, _valid_topic_no_wildcards(rng)))
    for _ in range(rng.randint(2, 5)):
        bag.extend(_utf8_slices(rng, _valid_sub_filter(rng)))
    # Client IDs (include empty chance to allow NULL id usage in harness via boolean)
    for _ in range(rng.randint(1, 3)):
        bag.append(_client_id(rng))
    # Usernames/passwords
    for _ in range(rng.randint(1, 3)):
        bag.append(_username(rng))
        bag.append(_password(rng))
    # PSK and identity
    bag.append(_psk_hex(rng))
    bag.append(_identity(rng))
    # Property names and values
    for _ in range(rng.randint(1, 3)):
        bag.append(_prop_name(rng))
        bag.append(_rand_utf8_text(rng, 0, rng.randint(4, 20), allow_extended=True))
    # Command names
    for _ in range(rng.randint(1, 3)):
        bag.append(_command_name(rng))
    # General fuzzable UTF-8 strings to feed various APIs
    for _ in range(rng.randint(3, 8)):
        bag.append(_rand_utf8_text(rng, 0, rng.randint(3, 24), allow_extended=True))
    # Ensure none contain embedded NUL; already guaranteed
    # Deduplicate occasionally to keep buffer smaller
    if rng.random() < 0.5:
        bag = list(dict.fromkeys(bag))
    return bag


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    bag = _bag_of_strings(rng)
    # Join with NUL separators so each FUZZ_PARAM_STR can read a distinct string.
    # Add a final trailing NUL to ensure the last string is properly terminated.
    data = ("\x00".join(bag) + "\x00").encode("utf-8")
    # Bound the size to <= 4096 bytes by trimming from the end if necessary
    if len(data) > 4096:
        data = data[:4096]
        # Ensure we end at a NUL to terminate the last string cleanly
        if data[-1:] != b"\x00":
            # backtrack to previous NUL if present, else append one (trimming one byte)
            last_nul = data.rfind(b"\x00")
            if last_nul != -1:
                data = data[: last_nul + 1]
            else:
                data = data[:-1] + b"\x00"
    return data
